// .incbin leaves the helper opaque to the compiler: no generated byte arrays,
// source maps or source changes per build. The final Bridge signature covers it.
#if defined(__APPLE__)
.section __TEXT,__const
.globl _np_claude_reader_start
_np_claude_reader_start:
#ifdef NORTHPANE_CLAUDE_READER_FILE
.incbin NORTHPANE_CLAUDE_READER_FILE
#endif
.globl _np_claude_reader_end
_np_claude_reader_end:
#else
.section .rodata
.globl np_claude_reader_start
np_claude_reader_start:
#ifdef NORTHPANE_CLAUDE_READER_FILE
.incbin NORTHPANE_CLAUDE_READER_FILE
#endif
.globl np_claude_reader_end
np_claude_reader_end:
#ifdef NORTHPANE_CLAUDE_READER_FILE
.globl np_reader_js_start, np_reader_js_end
np_reader_js_start:
.incbin NORTHPANE_CLAUDE_READER_JS
np_reader_js_end:
.globl np_reader_musl_start, np_reader_musl_end
np_reader_musl_start:
.incbin NORTHPANE_CLAUDE_READER_MUSL
np_reader_musl_end:
.globl np_reader_gcc_start, np_reader_gcc_end
np_reader_gcc_start:
.incbin NORTHPANE_CLAUDE_READER_GCC
np_reader_gcc_end:
.globl np_reader_cxx_start, np_reader_cxx_end
np_reader_cxx_start:
.incbin NORTHPANE_CLAUDE_READER_CXX
np_reader_cxx_end:
#endif
.section .note.GNU-stack,"",@progbits
#endif
